import random
from fractions import Fraction

def ruin_by_stopping(i, N, p):
    """(chance of reaching N before 0, expected number of bets)
    from i, when each bet wins with chance p, by the martingale formulas."""
    p = Fraction(p)
    q = 1 - p
    if i == 0 or i == N:
        return Fraction(1 if i == N else 0), Fraction(0)
    if p == q:
        return Fraction(i, N), Fraction(i * (N - i))
    r = q / p
    win = (1 - r**i) / (1 - r**N)
    return win, (N * win - i) / (p - q)

def wald_total(seed, games):
    """Average total of the rolls when a die is rolled until the
    first 6, over the given number of games."""
    rng = random.Random(seed)
    total = 0
    for _ in range(games):
        while True:
            roll = rng.randint(1, 6)
            total += roll
            if roll == 6:
                break
    return total / games
